/// <summary>
///     The <c>AVAAVATOSDetails_AVAUpdateAVAEmailInvoiceFromCustAccountBtn_Extension</c> class is the extension of FormControl <c>AVAInventTransferLineBundleExplode</c> in form <c>AVATOSDetails</c>
/// </summary>
[ExtensionOf(formControlStr(AVATOSDetails, AVAUpdateAVAEmailInvoiceFromCustAccount))]
final class AVAAVATOSDetails_AVAUpdateAVAEmailInvoiceFromCustAccountBtn_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>Clicked</c> class.
/// </summary>
public void clicked()
{
    FormDataSource      locFormDataSource;
    KCS_TOSTableCustTmp locBuffer;

    FormDataSource      locKCS_TOSTableDs;
    KCS_TOSTable        locKCS_TOSTable;

    locFormDataSource   = element.KCS_TOSTableCustTmp_DS;
    locKCS_TOSTableDs   = element.KCS_TOSTable_DS;
    locKCS_TOSTable     = locKCS_TOSTableDs.cursor();       // root KCS_TOSTable

    next clicked();

    locBuffer = locFormDataSource.cursor();
    //locKCS_TOSTable     = locBuffer.avaKCS_TOSTable();      // use root KCS_TOSTable from actual datasource instead of KCS_TOSTable of corresponding TOSId in perhaps deeper level
    if(locKCS_TOSTable.RecId)
    {
        locKCS_TOSTable.updateAVAEmailInvoiceFromCustAccount(locBuffer.CustAccount, true);
    }

    locFormDataSource = element.KCS_TOSTable_DS;
    locFormDataSource.reRead();
    locFormDataSource.refresh();
}
